/**
 * Access to the real Airtable base that integration tests run against.
 *
 * Tests normally get these through the fixtures in `./fixtures.ts`.
 */

import { type Airtable, createAirtable } from "../client.ts";
import { type BaseClient, createBaseClient } from "../typed/base-client.ts";
// @ts-ignore - This file is generated by running 'pnpm run ensure-test-base'
import testBaseSchema from "./test-base-schema.generated.ts";
import dotenv from "dotenv";
import { BaseId } from "../bases/types.ts";
import { WorkspaceId } from "../workspaces/types.ts";
import { TableSchema } from "../tables/types.ts";
import { AirtableKitApiError } from "../exceptions.ts";
import { getAllTypesSeedData, linkedItemsSeedData, tasksSeedData } from "./seed-data.ts";

export { testBaseSchema };

export interface TestEnv {
    AIRTABLE_KIT_TEST_API_KEY: string;
    AIRTABLE_KIT_TEST_BASE_ID: BaseId;
    AIRTABLE_KIT_TEST_WORKSPACE_ID: WorkspaceId;
}

/** Load test environment variables from .env file into process.env, and return them as a TestEnv object */
export function getTestEnv(env?: NodeJS.ProcessEnv): TestEnv {
    let loadFrom = env;
    if (!loadFrom) {
        dotenv.config({ quiet: true });
        loadFrom = process.env;
    }
    const {
        AIRTABLE_KIT_TEST_API_KEY,
        AIRTABLE_KIT_TEST_BASE_ID,
        AIRTABLE_KIT_TEST_WORKSPACE_ID,
    } = loadFrom;

    if (
        !AIRTABLE_KIT_TEST_API_KEY ||
        !AIRTABLE_KIT_TEST_BASE_ID ||
        !AIRTABLE_KIT_TEST_WORKSPACE_ID
    ) {
        throw new Error(
            "Missing required environment variables. Please set AIRTABLE_KIT_TEST_API_KEY, AIRTABLE_KIT_TEST_BASE_ID, and AIRTABLE_KIT_TEST_WORKSPACE_ID in your .env file.",
        );
    }
    return {
        AIRTABLE_KIT_TEST_API_KEY,
        AIRTABLE_KIT_TEST_BASE_ID: AIRTABLE_KIT_TEST_BASE_ID as BaseId,
        AIRTABLE_KIT_TEST_WORKSPACE_ID: AIRTABLE_KIT_TEST_WORKSPACE_ID as WorkspaceId,
    };
}

/** An {@link Airtable} client using the test API key from the environment */
export function getTestAirtable(): Airtable {
    return createAirtable({ apiKey: getTestEnv().AIRTABLE_KIT_TEST_API_KEY });
}

/**
 * A {@link BaseClient} for the test base with no valid API key,
 * for tests that only read the schema and make no requests.
 */
export const offlineTestBase = createBaseClient(testBaseSchema, { apiKey: "offline" });

/** A {@link BaseClient} for the test base, plus helpers to put its data in a known state. */
export interface TestBase extends BaseClient<typeof testBaseSchema> {
    /** Delete every record in every table, then write the seed data from `./seed-data.ts`. */
    reset(): Promise<void>;
    /** Delete every record in every table. */
    clear(): Promise<void>;
}

export function createTestBase(airtable: Airtable = getTestAirtable()): TestBase {
    const client = createBaseClient(testBaseSchema, airtable);
    const { tasks, linkedItems, allTypes } = client.tables;

    async function clear() {
        await allSettled(testBaseSchema.tables.map((table) => deleteAllRecords(airtable, testBaseSchema.id, table)));
    }

    async function seed() {
        await allSettled([
            tasks.createRecords(tasksSeedData),
            (async () => {
                const { records } = await linkedItems.createRecords(linkedItemsSeedData);
                await allTypes.createRecords(getAllTypesSeedData(records.map((r) => r.id)));
            })(),
        ]);
    }

    return {
        ...client,
        clear,
        async reset() {
            await clear();
            await seed();
        },
    };
}

/**
 * Delete every record in a table.
 *
 * A test that timed out keeps running in the background and may delete records
 * between our list and our delete, so Airtable answers 404 for those IDs.
 * When that happens, list again and retry.
 */
export async function deleteAllRecords(
    airtable: Airtable,
    baseId: BaseId,
    table: Pick<TableSchema, "id" | "primaryFieldId">,
    maxAttempts = 5,
): Promise<void> {
    for (let attempt = 1; ; attempt++) {
        // Raw records, so a record with values the typed client can't read can still be deleted.
        // Request only the primary field, to keep the response small.
        const records = await airtable.records.list({ baseId, tableId: table.id, fields: table.primaryFieldId ? [table.primaryFieldId] : undefined });
        if (records.length === 0) {
            return;
        }
        try {
            await airtable.records.delete({ baseId, tableId: table.id, recordIds: records.map((r) => r.id) });
            return;
        } catch (error) {
            if (!(error instanceof AirtableKitApiError && error.status === 404) || attempt >= maxAttempts) {
                throw error;
            }
        }
    }
}

/**
 * Wait for every promise, then throw the first rejection, if any.
 *
 * Unlike Promise.all, no request is still running once this settles,
 * so a failed reset can't write records into the next test.
 */
async function allSettled(promises: Promise<unknown>[]): Promise<void> {
    const results = await Promise.allSettled(promises);
    const failure = results.find((r) => r.status === "rejected");
    if (failure) {
        throw failure.reason;
    }
}
